import{_ as l,o as a,c as s,a6 as n}from"./chunks/framework.BlDtR6jM.js";const r="/Art_web_public/assets/npc_03.8N15-iSE.png",g="/Art_web_public/assets/npc_04.1qu3JbMQ.png",o="/Art_web_public/assets/npc_02.COml6pzo.png",t="/Art_web_public/assets/npc_00.DbWg2nAY.png",p=JSON.parse('{"title":"NPC 列表 (NPC List)","description":"","frontmatter":{"readingTime":"9 min read"},"headers":[],"relativePath":"项目实践/JRPG/C_世界与探索/02_生态与交互/NPC列表.md","filePath":"项目实践/JRPG/C_世界与探索/02_生态与交互/NPC列表.md"}'),i={name:"项目实践/JRPG/C_世界与探索/02_生态与交互/NPC列表.md"};function d(x,e,y,f,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="npc-列表-npc-list" tabindex="-1">NPC 列表 (NPC List) <a class="header-anchor" href="#npc-列表-npc-list" aria-label="Permalink to &quot;NPC 列表 (NPC List)&quot;">​</a></h1><blockquote><p>本文档列出了游戏中出现的关键非玩家角色，名称与设定已适配《神遗：蒸汽妖都》的世界观（东方神话 + 蒸汽朋克）。</p></blockquote><h2 id="_1-开篇-青炉镇-chapter-1-cyan-furnace-town" tabindex="-1">1. 开篇：青炉镇 (Chapter 1: Cyan Furnace Town) <a class="header-anchor" href="#_1-开篇-青炉镇-chapter-1-cyan-furnace-town" aria-label="Permalink to &quot;1. 开篇：青炉镇 (Chapter 1: Cyan Furnace Town)&quot;">​</a></h2><p><strong>场景</strong>：主角在废墟中醒来，仅存机械义肢，进入青炉镇寻找身世线索。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+r+'" alt="alt text"></td><td style="text-align:left;"><strong>镇长·葛洪 (Mayor Ge)</strong></td><td style="text-align:left;"><strong>青炉镇镇长</strong>。管理着镇中心的&quot;青铜炼炉&quot;，痴迷于将道家丹术与蒸汽锅炉结合，经常自言自语关于&quot;长生蒸汽&quot;的理论。</td></tr><tr><td style="text-align:left;"><img src="'+g+'" alt="alt text"></td><td style="text-align:left;"><strong>灵枢堂主·素问 (Doctor Su)</strong></td><td style="text-align:left;"><strong>灵枢堂医师</strong>。自称神农后裔，脸上常戴着防毒面具。她用银针刺激穴位，并配合炼金药剂治疗&quot;排异反应&quot;。</td></tr><tr><td style="text-align:left;"><img src="'+o+'" alt="alt text"></td><td style="text-align:left;"><strong>铁匠·欧冶子 (Master Ou)</strong></td><td style="text-align:left;"><strong>赤锤军械铺老板</strong>。左臂是巨大的液压钳。他不只是打铁，更精通精密齿轮的铆接，知晓&quot;断剑&quot;中隐藏的古代科技。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>天工使者·玉瑶 (Envoy Yu)</strong></td><td style="text-align:left;"><strong>天工剑盟特使</strong>。外表是大家闺秀，实则背负着监视青炉镇灵力波动的任务。赠予主角一枚&quot;龙纹齿轮&quot;后遭遇袭击。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>督军·铁浮屠 (Warlord Iron)</strong></td><td style="text-align:left;"><strong>驻军统领</strong>。全身重型板甲，信奉&quot;血肉苦弱&quot;。他在暗中搜集&quot;娲石碎片&quot;，是初期的幕后黑手。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>巡逻队长 (Patrol Captain)</strong></td><td style="text-align:left;"><strong>机械卫兵</strong>。负责把守城门，装备着老式的蒸汽步枪，对未登记的改造人非常警惕。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>废品拾荒者 (Scrap Collector)</strong></td><td style="text-align:left;"><strong>情报贩子</strong>。躲在管道缝隙中的小乞丐，身上挂满废弃零件。知道镇地下&quot;排污管道&quot;的秘密入口。</td></tr></tbody></table><hr><h2 id="_2-新手阶段-试炼与成长-training-phase" tabindex="-1">2. 新手阶段：试炼与成长 (Training Phase) <a class="header-anchor" href="#_2-新手阶段-试炼与成长-training-phase" aria-label="Permalink to &quot;2. 新手阶段：试炼与成长 (Training Phase)&quot;">​</a></h2><p><strong>场景</strong>：天机武馆与初期探索。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>馆长·雷万钧 (Master Lei)</strong></td><td style="text-align:left;"><strong>天机武馆馆长</strong>。退役老兵，传授&quot;蒸汽动力拳法&quot;。在演武场演示如何用蒸汽喷射加速出拳。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>学徒·阿吉 (Apprentice Aji)</strong></td><td style="text-align:left;"><strong>赤锤军械铺学徒</strong>。帮助主角修复破损的初始武器，梦想是制造出能飞的机械鸟。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>机关教头 (Drill Automaton)</strong></td><td style="text-align:left;"><strong>训练用木人桩</strong>。加装了简单的自动反击装置，引导玩家熟悉战斗系统。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>老板娘·铜嫂 (Madame Brass)</strong></td><td style="text-align:left;"><strong>铜管酒肆老板娘</strong>。性格泼辣，消息灵通。出售&quot;机油黑啤&quot;和周边的粗略地图。</td></tr></tbody></table><hr><h2 id="_3-探索阶段-荒原与矿山-exploration-phase" tabindex="-1">3. 探索阶段：荒原与矿山 (Exploration Phase) <a class="header-anchor" href="#_3-探索阶段-荒原与矿山-exploration-phase" aria-label="Permalink to &quot;3. 探索阶段：荒原与矿山 (Exploration Phase)&quot;">​</a></h2><p><strong>场景</strong>：苍狼矿山与月白重工区周边。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>唐门·暗哨 (Tang Sect Agent)</strong></td><td style="text-align:left;"><strong>赏金猎人</strong>。擅长使用淬毒的机械暗器。在竹林布下陷阱，可能会赠送主角&quot;暴雨梨花针&quot;的设计图。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>变异药师 (Mutant Herbalist)</strong></td><td style="text-align:left;"><strong>流浪医生</strong>。长期暴露在辐射下导致身体变异，在瘴气林中用蛊虫和化学试剂解毒。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>荒原猎人 (Wasteland Hunter)</strong></td><td style="text-align:left;"><strong>生存专家</strong>。全身披着伪装网，教授如何在机械残骸中寻找可用的能源电池。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>废铁帮主 (Scrap Gang Leader)</strong></td><td style="text-align:left;"><strong>矿山强盗头目</strong>。驾驶着简易拼凑的机甲，作为苍狼矿山的第一个小Boss。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>黑莲隐士 (Lotus Hermit)</strong></td><td style="text-align:left;"><strong>神秘方士</strong>。躲藏在废弃寺庙中，研究被禁止的&quot;血肉飞升&quot;法术，是魔教的先锋。</td></tr></tbody></table><hr><h2 id="_4-中期阶段-城市与阴谋-mid-game-cities-conflicts" tabindex="-1">4. 中期阶段：城市与阴谋 (Mid-Game: Cities &amp; Conflicts) <a class="header-anchor" href="#_4-中期阶段-城市与阴谋-mid-game-cities-conflicts" aria-label="Permalink to &quot;4. 中期阶段：城市与阴谋 (Mid-Game: Cities &amp; Conflicts)&quot;">​</a></h2><p><strong>场景</strong>：上海、伦敦等大都会区域。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>走私贩 (Smuggler)</strong></td><td style="text-align:left;"><strong>黑市商人</strong>。在阴暗的巷子里兜售违禁的&quot;高纯度以太&quot;和未注册的义肢插件。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>丝绸商 (Silk Merchant)</strong></td><td style="text-align:left;"><strong>伪装的特工</strong>。表面卖布，实则出售具有防弹功能的纳米纤维织物。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>运河船夫 (Canal Boatman)</strong></td><td style="text-align:left;"><strong>水路向导</strong>。熟悉城市地下的排水系统，协助主角潜入戒备森严的工厂。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>机关雕刻师 (Gear Carver)</strong></td><td style="text-align:left;"><strong>锁匠</strong>。能制作精密的齿轮钥匙，解开古老的鲁班锁机关。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>天命算师 (Destiny Calculator)</strong></td><td style="text-align:left;"><strong>占卜师</strong>。使用差分机进行算命，指引主角下一步的&quot;概率最大&quot;行动。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>鬼市牙佬 (Ghost Market Broker)</strong></td><td style="text-align:left;"><strong>情报中介</strong>。在地下黑市贩卖《天魔策》残卷（古代基因编辑技术）。</td></tr></tbody></table><hr><h2 id="_5-高潮阶段-决战前夕-late-game" tabindex="-1">5. 高潮阶段：决战前夕 (Late Game) <a class="header-anchor" href="#_5-高潮阶段-决战前夕-late-game" aria-label="Permalink to &quot;5. 高潮阶段：决战前夕 (Late Game)&quot;">​</a></h2><p><strong>场景</strong>：反派大本营与最终迷宫。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>背叛者 (The Traitor)</strong></td><td style="text-align:left;"><strong>双面间谍</strong>。在关键时刻泄露了天工剑盟的防线图，导致主角团陷入危机。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>剑盟宗主 (Alliance Master)</strong></td><td style="text-align:left;"><strong>正道领袖</strong>。试图用&quot;轩辕剑阵&quot;封印即将苏醒的机械邪神。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>军火大亨 (Arms Dealer)</strong></td><td style="text-align:left;"><strong>中立商人</strong>。只认钱不认人，在大战前夕出售终极武器组件。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>守陵人 (Tomb Keeper)</strong></td><td style="text-align:left;"><strong>古代AI投影</strong>。守护着女娲祭坛，要求主角以血（基因）验证身份。</td></tr></tbody></table><hr><h2 id="_6-结局-finale" tabindex="-1">6. 结局 (Finale) <a class="header-anchor" href="#_6-结局-finale" aria-label="Permalink to &quot;6. 结局 (Finale)&quot;">​</a></h2><p><strong>场景</strong>：最终Boss战与尾声。</p><table tabindex="0"><thead><tr><th style="text-align:left;">截图</th><th style="text-align:left;">名称 (Name)</th><th style="text-align:left;">身份与描述 (Identity &amp; Description)</th></tr></thead><tbody><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>灭世·蚩尤 (Mecha-Chiyou)</strong></td><td style="text-align:left;"><strong>最终Boss</strong>。上古魔神与现代重工技术的终极结合体，妄图重塑世界。</td></tr><tr><td style="text-align:left;"><img src="'+t+'" alt="alt text"></td><td style="text-align:left;"><strong>游吟诗人 (The Bard)</strong></td><td style="text-align:left;"><strong>记录者</strong>。在一切结束后，坐在废墟之上，弹着吉他传唱这段&quot;齿轮与神话&quot;的传奇。</td></tr></tbody></table>',25)])])}const u=l(i,[["render",d]]);export{p as __pageData,u as default};
